CANVAS = CANVAS.replace("<H1>Tool palette: two icon directions</H1>", '''<H1>Tool palette: primary icons and tool families</H1><H2>New · Primary palette icons</H2>{['Slate','File Atlas'].map(app=><section key={app}><H2>{app}</H2><div style={{display:'flex',gap:12,flexWrap:'wrap',marginBottom:16}}>{primaryIcons.filter(i=>i.app===app).map(i=><button key={i.name} title={i.why} onClick={()=>setSelected(i.name)} style={{width:90,padding:8,border:`1px solid ${t.stroke.primary}`,borderRadius:6,background:selected===i.name?t.accent.control:t.bg.elevated,color:selected===i.name?t.text.onAccent:t.text.primary,cursor:'pointer'}}>{glyph(i,false)}<div style={{fontSize:11,marginTop:8}}>{i.name}</div></button>)}</div></section>)}<Text>{primaryIcons.find(i=>i.name===selected)?.why || 'Select a primary icon to read its design reasoning.'}</Text><H2>Individual tools</H2>''')
canvas_path.write_text(CANVAS.replace('__PRIMARY__',json.dumps(PRIMARY)).replace('__DATA__',json.dumps(DATA)).replace('__RULES__',json.dumps(RULES)),encoding='utf-8')
print(ROOT/'proposal.html')
